`compileLayers(layers)` validates and compiles a flat visual composition. Every layer needs a nonblank unique ID, a finite depth, and opacity from 0 through 1 inclusive. An empty input is valid. Return newly allocated objects ordered by ascending depth; equal-depth layers retain their input order. Each output includes `visible`, which is true exactly when opacity is greater than zero.

The input array and its objects must not be mutated or reordered. The returned array and objects must not alias the input.

Known-bad source:

```typescript
export interface Layer {
  id: string;
  depth: number;
  opacity: number;
}

export interface CompiledLayer {
  id: string;
  depth: number;
  opacity: number;
  visible: boolean;
}

export function compileLayers(layers: Layer[]): CompiledLayer[] {
  const ids = new Set<string>();
  for (const layer of layers) {
    if (layer.id.trim().length === 0) throw new RangeError("blank id");
    if (ids.has(layer.id)) throw new RangeError("duplicate id");
    ids.add(layer.id);
    if (!Number.isFinite(layer.depth)) throw new RangeError("invalid depth");
    if (!Number.isFinite(layer.opacity) || layer.opacity < 0 || layer.opacity > 1) {
      throw new RangeError("invalid opacity");
    }
  }
  return layers
    .sort((left, right) => left.depth - right.depth)
    .map((layer) => ({ ...layer, visible: layer.opacity > 0 }));
}
```

