import { compileLayers, Layer } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const empty: Layer[] = [];
const emptyResult = compileLayers(empty);
deepEqual(emptyResult, [], 'empty input is valid');
assert(emptyResult !== empty, 'empty result is newly allocated');
assert(compileLayers(empty) !== emptyResult, 'empty results are independent');

const layers: Layer[] = [
  { id: ' front ', depth: 5, opacity: 1 },
  { id: 'hidden', depth: -2, opacity: 0 },
  { id: 'middle-a', depth: 1, opacity: 0.5 },
  { id: 'middle-b', depth: 1, opacity: Number.MIN_VALUE }
];
const snapshot = JSON.stringify(layers);
const compiled = compileLayers(layers);
deepEqual(compiled.map((layer) => layer.id), ['hidden', 'middle-a', 'middle-b', ' front '], 'ascending stable depth order');
deepEqual(compiled.map((layer) => layer.visible), [false, true, true, true], 'visibility follows opacity greater than zero');
deepEqual(compiled.map((layer) => layer.opacity), [0, 0.5, Number.MIN_VALUE, 1], 'opacity values are preserved');
deepEqual(JSON.stringify(layers), snapshot, 'input array and objects are not changed or reordered');
for (const output of compiled) {
  const input = layers.find((layer) => layer.id === output.id);
  assert(output !== input, `output ${output.id} does not alias input`);
}
const again = compileLayers(layers);
assert(again !== compiled, 'result array is newly allocated');
for (let index = 0; index < compiled.length; index += 1) {
  assert(again[index] !== compiled[index], `output ${index} is newly allocated per call`);
}

throwsRange(() => compileLayers([{ id: ' \t ', depth: 0, opacity: 1 }]), 'blank id');
throwsRange(() => compileLayers([{ id: 'same', depth: 0, opacity: 1 }, { id: 'same', depth: 1, opacity: 1 }]), 'duplicate id');
for (const depth of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  throwsRange(() => compileLayers([{ id: 'x', depth, opacity: 1 }]), 'nonfinite depth');
}
for (const opacity of [-Number.MIN_VALUE, 1 + Number.EPSILON, Number.NaN, Number.POSITIVE_INFINITY]) {
  throwsRange(() => compileLayers([{ id: 'x', depth: 0, opacity }]), 'invalid opacity');
}
deepEqual(compileLayers([{ id: 'zero', depth: 0, opacity: 0 }, { id: 'one', depth: 1, opacity: 1 }]).map((layer) => layer.visible), [false, true], 'opacity boundaries are accepted');

